  34: /// Parse a custom charset definition string into a charset.
  35: ///
  36: /// Custom charset definitions can contain:
  37: /// - Built-in tokens like `?l`, `?d`, `?u`, etc. which expand to their charsets
  38: /// - Literal characters
  39: ///
  40: /// For example: `?l?d` expands to lowercase letters + digits,
  41: /// `aeiou` is just those 5 vowels, `?l@#$` is lowercase + @, #, $.
  42: pub fn parse_custom_charset(definition: &str) -> Result<Vec<char>, FinderError> {
  43:     let mut charset = Vec::new();
  44:     let mut chars = definition.chars();
  45: 
  46:     while let Some(c) = chars.next() {
  47:         if c == '?' {
  48:             match chars.next() {
  49:                 Some('?') => charset.push('?'),
  50:                 Some(token) => {
  51:                     if let Some(builtin) = resolve_builtin_token(token) {
  52:                         charset.extend(builtin);
  53:                     } else {
  54:                         return Err(CliArgumentError {
  55:                             message: format!(
  56:                                 "Unknown token '?{token}' in custom charset definition"
  57:                             ),
  58:                         });
  59:                     }
  60:                 }
  61:                 None => {
  62:                     return Err(CliArgumentError {
  63:                         message: "Custom charset definition ends with incomplete token '?'"
  64:                             .to_string(),
  65:                     });
  66:                 }
  67:             }
  68:         } else {
  69:             charset.push(c);
  70:         }
  71:     }
  72: 
  73:     if charset.is_empty() {
  74:         return Err(CliArgumentError {
  75:             message: "Custom charset definition is empty".to_string(),
  76:         });
  77:     }
  78: 
  79:     // deduplicate while preserving order
  80:     let mut seen = Vec::with_capacity(charset.len());
  81:     for c in charset {
  82:         if !seen.contains(&c) {
  83:             seen.push(c);
  84:         }
  85:     }
  86: 
  87:     Ok(seen)
