  93: /// Parse a mask pattern string into a `ParsedMask`.
  94: ///
  95: /// Mask tokens:
  96: /// - `?l` = lowercase letters (a-z)
  97: /// - `?u` = uppercase letters (A-Z)
  98: /// - `?d` = digits (0-9)
  99: /// - `?s` = symbols
 100: /// - `?a` = all printable (l+u+d+s)
 101: /// - `?h` = lowercase hex (0-9a-f)
 102: /// - `?H` = uppercase hex (0-9A-F)
 103: /// - `?1`..`?4` = custom charsets
 104: /// - `??` = literal '?'
 105: /// - Any other character = literal
 106: pub fn parse_mask(mask: &str, custom_charsets: &CustomCharsets) -> Result<ParsedMask, FinderError> {
 107:     let mut positions = Vec::new();
 108:     let mut chars = mask.chars();
 109: 
 110:     while let Some(c) = chars.next() {
 111:         if c == '?' {
 112:             match chars.next() {
 113:                 Some('?') => positions.push(vec!['?']),
 114:                 Some(token @ '1'..='4') => {
 115:                     let idx = (token as usize) - ('1' as usize);
 116:                     match &custom_charsets[idx] {
 117:                         Some(charset) => positions.push(charset.clone()),
 118:                         None => {
 119:                             return Err(CliArgumentError {
 120:                                 message: format!(
 121:                                     "Custom charset ?{token} used in mask but --customCharset{token} not provided"
 122:                                 ),
 123:                             });
 124:                         }
 125:                     }
 126:                 }
 127:                 Some(token) => {
 128:                     if let Some(builtin) = resolve_builtin_token(token) {
 129:                         positions.push(builtin);
 130:                     } else {
 131:                         return Err(CliArgumentError {
 132:                             message: format!("Unknown mask token '?{token}'"),
 133:                         });
 134:                     }
 135:                 }
 136:                 None => {
 137:                     return Err(CliArgumentError {
 138:                         message: "Mask ends with incomplete token '?'".to_string(),
 139:                     });
 140:                 }
 141:             }
 142:         } else {
 143:             positions.push(vec![c]);
 144:         }
 145:     }
 146: 
 147:     if positions.is_empty() {
 148:         return Err(CliArgumentError {
 149:             message: "Mask pattern is empty".to_string(),
 150:         });
 151:     }
 152: 
 153:     Ok(ParsedMask { positions })
 154: }
