 161: struct MaskPasswordGenerator {
 162:     positions: Vec<Vec<u8>>,
 163:     indices: Vec<usize>,
 164:     total: usize,
 165:     generated: usize,
 166:     finished: bool,
 167: }
 168: 
 169: impl MaskPasswordGenerator {
 170:     fn new(mask: ParsedMask) -> Self {
 171:         let total = mask_password_count(&mask);
 172:         let len = mask.positions.len();
 173:         // Convert char positions to u8 once at construction
 174:         let positions = mask
 175:             .positions
 176:             .into_iter()
 177:             .map(|chars| chars.into_iter().map(|c| c as u8).collect())
 178:             .collect();
 179:         Self {
 180:             positions,
 181:             indices: vec![0; len],
 182:             total,
 183:             generated: 0,
 184:             finished: total == 0,
 185:         }
 186:     }
 187: 
 188:     fn current_password(&self) -> Vec<u8> {
 189:         self.indices
 190:             .iter()
 191:             .enumerate()
 192:             .map(|(pos, &idx)| self.positions[pos][idx])
 193:             .collect()
 194:     }
 195: }
 196: 
 197: impl Iterator for MaskPasswordGenerator {
 198:     type Item = Vec<u8>;
 199: 
 200:     fn next(&mut self) -> Option<Self::Item> {
 201:         if self.finished {
 202:             return None;
 203:         }
 204: 
 205:         let password = self.current_password();
 206:         self.generated += 1;
 207: 
 208:         if self.generated == self.total {
 209:             self.finished = true;
 210:         } else {
 211:             // Increment: rightmost position first (odometer style)
 212:             let mut carry = true;
 213:             for i in (0..self.indices.len()).rev() {
 214:                 if carry {
 215:                     self.indices[i] += 1;
 216:                     if self.indices[i] >= self.positions[i].len() {
 217:                         self.indices[i] = 0;
 218:                     } else {
 219:                         carry = false;
 220:                     }
 221:                 }
 222:             }
 223:         }
 224: 
 225:         Some(password)
 226:     }
 227: 
 228:     fn size_hint(&self) -> (usize, Option<usize>) {
 229:         let remaining = self.total - self.generated;
 230:         (remaining, Some(remaining))
 231:     }
 232: }
 233: 
 234: pub fn mask_password_iter(mask: ParsedMask) -> impl Iterator<Item = Vec<u8>> {
 235:     MaskPasswordGenerator::new(mask)
 236: }
