    fn test_combined_charsets() {
        let charset = preset_to_charset("lu").unwrap();
        assert_eq!(
            charset,
            [charset_lowercase_letters(), charset_uppercase_letters()].concat()
        );

        let charset = preset_to_charset("lud").unwrap();
        assert_eq!(
